export function useUiText() {
  const language = useLang()?.lang || 'en';
  const index = ['ta', 'gu', 'pa'].indexOf(language);
  return text => index < 0 ? authTranslations[text]?.[['te','hi'].indexOf(language)] || legacyPlanCopy[language]?.[text] || text : appUi[text]?.[index] || countedText(text, index) || text;
}

const legacyPlanCopy = {
  te: {'Everyday connection for one parent':'ఒక తల్లిదండ్రితో రోజువారీ అనుబంధం', 'Daily routines for two parents':'ఇద్దరు తల్లిదండ్రుల రోజువారీ సంరక్షణ', 'Shared care — keep your family connected':'కుటుంబంతో పంచుకునే సంరక్షణ', 'Recommended':'సిఫార్సు', 'Monthly':'నెలవారీ', 'Annual':'సంవత్సరానికి'},
  hi: {'Everyday connection for one parent':'एक माता या पिता से रोज़ का जुड़ाव', 'Daily routines for two parents':'दो माता-पिता की रोज़ की दिनचर्या', 'Shared care — keep your family connected':'परिवार के साथ साझा देखभाल', 'Recommended':'सुझाव', 'Monthly':'मासिक', 'Annual':'वार्षिक'},
};
function countedText(text, index) {
  if (typeof text !== 'string') return text;
  let match = text.match(/^Up to (\d+) check-ins \+ (\d+) activities per day, per parent \(water uses an activity slot\)$/);
  if (match) return [
    `ஒரு பெற்றோருக்கு தினமும் ${match[1]} விசாரிப்புகள் + ${match[2]} செயல்கள் வரை (தண்ணீரும் ஒரு செயல்)`,
    `દરેક માતાપિતા માટે રોજ ${match[1]} ચેક-ઇન + ${match[2]} પ્રવૃત્તિ સુધી (પાણી પણ એક પ્રવૃત્તિ)`,
    `ਹਰ ਮਾਪੇ ਲਈ ਰੋਜ਼ ${match[1]} ਚੈੱਕ-ਇਨ + ${match[2]} ਕੰਮ ਤੱਕ (ਪਾਣੀ ਵੀ ਇੱਕ ਕੰਮ)`][index];
  match = text.match(/^(\d+) medicine reminder slots per day, per parent(.*)$/);
  if (match) return [
    `ஒரு பெற்றோருக்கு தினமும் ${match[1]} மருந்து நினைவூட்டல்கள்${match[2] ? '; 30 நாட்கள் வரை 2 கூடுதல் மீட்பு நினைவூட்டல்கள்' : ''}`,
    `દરેક માતાપિતા માટે રોજ ${match[1]} દવાના રિમાઇન્ડર${match[2] ? '; 30 દિવસ સુધી 2 વધારાના રિકવરી રિમાઇન્ડર' : ''}`,
    `ਹਰ ਮਾਪੇ ਲਈ ਰੋਜ਼ ${match[1]} ਦਵਾਈ ਦੀਆਂ ਯਾਦਾਂ${match[2] ? '; 30 ਦਿਨਾਂ ਤੱਕ 2 ਵਾਧੂ ਰਿਕਵਰੀ ਯਾਦਾਂ' : ''}`
  ][index];
  match = text.match(/^(\d+) safety return checks per week, per parent$/);
  if (match) return [`ஒரு பெற்றோருக்கு வாரம் ${match[1]} வீடு திரும்பும் விசாரிப்புகள்`, `દરેક માતાપિતા માટે અઠવાડિયે ${match[1]} ઘરે પહોંચવાની તપાસ`, `ਹਰ ਮਾਪੇ ਲਈ ਹਫ਼ਤੇ ਵਿੱਚ ${match[1]} ਘਰ ਪਹੁੰਚਣ ਦੀਆਂ ਜਾਂਚਾਂ`][index];
  match = text.match(/^(.*?) billed once per year for 12 months of access\.$/);
  if (match) return [`12 மாதங்களுக்கு ஆண்டுதோறும் ஒருமுறை ${match[1]} கட்டணம்.`, `12 મહિનાની ઍક્સેસ માટે વર્ષમાં એક વાર ${match[1]} ચાર્જ.`, `12 ਮਹੀਨਿਆਂ ਦੀ ਪਹੁੰਚ ਲਈ ਸਾਲ ਵਿੱਚ ਇੱਕ ਵਾਰ ${match[1]} ਚਾਰਜ।`][index];
  return null;
}
